// ratelimit/ratelimit.go
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock abstracts time so tests can drive it deterministically.
type Clock interface {
	Now() time.Time
}

// RealClock returns the system time.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }

// Bucket is a concurrency-safe token-bucket rate limiter.
//
// The bucket holds at most capacity tokens. It is refilled at rate
// tokens per second, continuously, and tokens are consumed atomically
// with AllowN.
type Bucket struct {
	mu       sync.Mutex
	clock    Clock
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
}

// NewBucket validates and returns a Bucket pre-filled to capacity.
//
// rate must be > 0 and finite; capacity must be > 0 and finite.
func NewBucket(clock Clock, rate, capacity float64) (*Bucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if math.IsNaN(rate) || math.IsInf(rate, 0) || rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive and finite")
	}
	if math.IsNaN(capacity) || math.IsInf(capacity, 0) || capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive and finite")
	}
	now := clock.Now()
	return &Bucket{
		clock:    clock,
		rate:     rate,
		capacity: capacity,
		tokens:   capacity,
		last:     now,
	}, nil
}

// AllowN reports whether n tokens can be consumed now. It never blocks.
//
// On success it atomically deducts n tokens. On failure the bucket state
// is left unchanged (no deduction). n must be > 0 and finite; otherwise
// AllowN returns false.
func (b *Bucket) AllowN(n float64) bool {
	if math.IsNaN(n) || math.IsInf(n, 0) || n <= 0 {
		return false
	}

	b.mu.Lock()
	defer b.mu.Unlock()

	now := b.clock.Now()
	elapsed := now.Sub(b.last).Seconds()
	if elapsed > 0 {
		b.tokens += elapsed * b.rate
		if b.tokens > b.capacity {
			b.tokens = b.capacity
		}
		b.last = now
	}

	if b.tokens < n {
		return false
	}
	b.tokens -= n
	return true
}
